import{_ as t,a}from"./chunks/compare-tempsweep.B68yRgr8.js";import{_ as r,o as i,c as o,ai as s}from"./chunks/framework.C33Uq6m-.js";const f=JSON.parse('{"title":"Compare","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/compare.md","filePath":"en/guide/compare.md"}'),n={name:"en/guide/compare.md"};function l(d,e,p,h,m,c){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="compare" tabindex="-1">Compare <a class="header-anchor" href="#compare" aria-label="Permalink to &quot;Compare&quot;">​</a></h1><p>The Compare page lets you run the same prompt through multiple models or settings simultaneously and compare the results side by side.</p><p><strong>Sidebar item:</strong> Compare <strong>Route:</strong> <code>/compare</code></p><p><img src="'+t+'" alt="Compare side by side"></p><h2 id="interface-overview" tabindex="-1">Interface Overview <a class="header-anchor" href="#interface-overview" aria-label="Permalink to &quot;Interface Overview&quot;">​</a></h2><p>The page has a prompt input area at the top and a configurable grid of <strong>slots</strong> below it. Each slot represents one model/settings combination.</p><h2 id="setting-up-slots" tabindex="-1">Setting Up Slots <a class="header-anchor" href="#setting-up-slots" aria-label="Permalink to &quot;Setting Up Slots&quot;">​</a></h2><ol><li>Click <strong>Add Slot</strong> to create a comparison slot (up to 4 slots).</li><li>For each slot, configure: <ul><li><strong>Model</strong> — Select from your installed Ollama models (embedding models are filtered out)</li><li><strong>Temperature</strong> — Controls randomness (0 = deterministic, higher = more creative)</li><li><strong>System prompt</strong> — Optional system-level instructions</li><li><strong>Sampling parameters</strong> — Top-k, top-p, seed, and other Ollama options</li></ul></li></ol><p>Each slot displays its settings as pills for quick reference.</p><h2 id="running-a-comparison" tabindex="-1">Running a Comparison <a class="header-anchor" href="#running-a-comparison" aria-label="Permalink to &quot;Running a Comparison&quot;">​</a></h2><ol><li>Type your prompt in the shared input area.</li><li>Click <strong>Run All</strong>. All slots stream their responses simultaneously.</li><li>Watch the results appear side by side in real time.</li></ol><h2 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h2><h3 id="grid-view" tabindex="-1">Grid View <a class="header-anchor" href="#grid-view" aria-label="Permalink to &quot;Grid View&quot;">​</a></h3><p>The default view. All slots display their streaming results in a grid layout. Each slot shows:</p><ul><li>The model response</li><li>A settings pill showing the model name and temperature</li></ul><h3 id="diff-view" tabindex="-1">Diff View <a class="header-anchor" href="#diff-view" aria-label="Permalink to &quot;Diff View&quot;">​</a></h3><p>Switch to diff view to see <strong>word-level highlighting</strong> of what changed between two outputs. Added text is highlighted green, removed text is highlighted red.</p><p><img src="'+a+'" alt="Compare temperature sweep"></p><h2 id="metrics-bar" tabindex="-1">Metrics Bar <a class="header-anchor" href="#metrics-bar" aria-label="Permalink to &quot;Metrics Bar&quot;">​</a></h2><p>Below the grid, a visual <strong>metrics bar</strong> compares key performance indicators across all slots:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Description</th></tr></thead><tbody><tr><td><strong>TTFT</strong></td><td>Time to first token — how fast each model started responding</td></tr><tr><td><strong>Tokens/sec</strong></td><td>Generation throughput</td></tr><tr><td><strong>Total tokens</strong></td><td>Completion token count</td></tr></tbody></table><h2 id="quick-presets" tabindex="-1">Quick Presets <a class="header-anchor" href="#quick-presets" aria-label="Permalink to &quot;Quick Presets&quot;">​</a></h2><p>One-click presets to set up common comparison scenarios:</p><ul><li><strong>Temperature Sweep</strong> — Same model at 3 different temperatures (0.2, 0.7, 1.2) to see how creativity changes</li><li><strong>Deterministic Pair</strong> — Same model, same seed, same settings — verifies reproducibility</li></ul><h2 id="saving-exporting-and-sharing" tabindex="-1">Saving, Exporting, and Sharing <a class="header-anchor" href="#saving-exporting-and-sharing" aria-label="Permalink to &quot;Saving, Exporting, and Sharing&quot;">​</a></h2><p>Comparison results are automatically saved to IndexedDB, and you can export them as JSON or Markdown, or share them to GitHub Discussions. These features are covered in detail in the <a href="./language-compare.html#saving-results">Language Compare</a> guide — they apply to all comparison types, not just language comparisons.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Same model, different settings</strong> is often more insightful than comparing different models. Try varying temperature or system prompts.</li><li><strong>Slots persist</strong> across page navigation within the session.</li><li>Use a <strong>low token count</strong> prompt for quick iterations.</li></ul>',28)])])}const b=r(n,[["render",l]]);export{f as __pageData,b as default};
